	private void runTypedTarget(Path path, boolean readyAtStart, boolean releaseBeforeFinish) throws Exception {
		CountDownLatch entered = new CountDownLatch(1);
		CountDownLatch release = new CountDownLatch(1);
		LmdbStore store = new HeldStore(path, entered, release);
		SailRepository repository = new SailRepository(store);
		repository.init();
		try {
			assertTrue(entered.await(10, TimeUnit.SECONDS));
			if (readyAtStart) {
				release.countDown();
				LmdbTestUtil.awaitPostReadyInitialization(store, 30, TimeUnit.SECONDS);
			}
			LmdbEvaluationStatistics statistics = (LmdbEvaluationStatistics) store.getBackingStore()
					.getEvaluationStatistics();
			long revision = statistics.estimatorRuntime().snapshotVersion();
			statistics.bindExecutionSnapshot(OptionalLong.of(revision));
			Filter node = filter();
			node.setCostFeedbackTrackingEnabled(true);
			LogicalLearningKey logical = LogicalLearningKey.of("filter", "condition", "children", "predicates",
					"v0", "none", "bag", "default");
			LearningApplicability applicability = new LearningApplicability(1L, 0L, "unconditional", revision,
					revision, 1L);
			PhysicalResidualKey physical = PhysicalResidualKey.of("filter", "statement-pattern", "spoc",
					"single", "none", "none", "none", "bound");
			RuntimeFeedbackContract.PredictionVector prediction = new RuntimeFeedbackContract.PredictionVector(
					1.0d, 1.0d, 1.0d, 1.0d, 0.0d, 1.0d, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d);
			RuntimeFeedbackContract contract = new RuntimeFeedbackContract(
					new LmdbRuntimeFeedbackDescriptor(null, null, logical, applicability, physical), prediction,
					prediction, 1.0d, 1.0d, 1.0d, Double.POSITIVE_INFINITY,
					RuntimeFeedbackContract.SemanticKind.ORDINARY, RuntimeFeedbackContract.Algorithm.STREAMING_CORRELATED,
					RuntimeFeedbackContract.Access.EXACT_LOOKUP, physical.hashCode(), revision, revision, 1L,
					RuntimeFeedbackContract.ADMIT_LOGICAL | RuntimeFeedbackContract.ADMIT_PHYSICAL);
			node.setRuntimeFeedbackContract(contract);
			assertTrue(statistics.shouldTrackCostFeedback(node), "a valid typed contract is trackable for this snapshot");
			RuntimeFeedbackTarget target = statistics.resolveRuntimeFeedbackTarget(node, contract);
			assertTrue(target.active(), "the typed operator has an execution-local feedback target");
			target.open();
			if (releaseBeforeFinish) {
				release.countDown();
				LmdbTestUtil.awaitPostReadyInitialization(store, 30, TimeUnit.SECONDS);
			}
			target.close(4L, 4.0d, 4L, 0L, 4L, 0L, 0L, 0L, 0L, 0L,
					EvaluationStatistics.TerminationClassification.EXHAUSTED);
			target.recordActualPhysicalImplementation(contract.physicalImplementationId());
			statistics.publishRuntimeFeedbackTargets(new RuntimeFeedbackTarget[] { target }, 1, true);
			if (!readyAtStart && !releaseBeforeFinish) {
				release.countDown();
				LmdbTestUtil.awaitPostReadyInitialization(store, 30, TimeUnit.SECONDS);
			}
			LmdbOperatorFeedbackStats feedback = ((LmdbEvaluationStatistics) store.getBackingStore()
					.getEvaluationStatistics()).estimatorRuntime().feedback();
			assertNotNull(feedback, "post-ready store exposes the provider");
			assertNotNull(feedback.logicalPosterior(logical, applicability, FrontierCostDimension.OUTPUT_ROWS),
					"the exact logical destination receives the completed observation");
			assertNotNull(feedback.physicalPosterior(logical, physical, applicability,
					FrontierCostDimension.EXPRESSION_EVALUATIONS),
					"the exact physical destination receives the completed observation");
		} finally {
			release.countDown();
			repository.shutDown();
		}
	}

	private enum Boundary {
		FINISH_BEFORE_PUBLICATION, COMMIT_BEFORE_PUBLICATION, COMMIT_AND_FINISH_BEFORE_PUBLICATION,
		COMMIT_AFTER_PUBLICATION
	}

	private void runQuery(Path path, Boundary boundary) throws Exception {
		CountDownLatch entered = new CountDownLatch(1);
		CountDownLatch release = new CountDownLatch(1);
		LmdbStore store = new HeldStore(path, entered, release);
		SailRepository repository = new SailRepository(store);
		repository.init();
		try {
			assertTrue(entered.await(10, TimeUnit.SECONDS), "the actual post-ready worker is held");
			populate(repository);
			if (boundary == Boundary.COMMIT_AFTER_PUBLICATION) {
				release.countDown();
				LmdbTestUtil.awaitPostReadyInitialization(store, 30, TimeUnit.SECONDS);
			}
			try (SailDataset dataset = store.getBackingStore().getExplicitSailSource()
					.dataset(IsolationLevels.SNAPSHOT_READ)) {
				var source = new SailDatasetTripleTermSource(store.getValueFactory(), dataset);
				long queryEpoch = source.getSnapshotEpoch().orElseThrow();
				var stats = (LmdbEvaluationStatistics) store.getBackingStore().getEvaluationStatistics();
				EvaluationStrategy strategy = store.getConnectionEvaluationStrategyFactory()
						.createEvaluationStrategy(null, source, stats, store.getQueryExecutionPolicy());
				assertInstanceOf(LmdbEvaluationStrategy.class, strategy);
				((LmdbEvaluationStrategy) strategy).setTrackResultSize(true);
				TupleExpr expression = QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL, QUERY, null).getTupleExpr();
				TupleExpr optimized = strategy.optimize(expression, stats, EmptyBindingSet.getInstance());
				QueryEvaluationStep step = strategy.precompile(optimized);
				Filter typed = findFilter(optimized, true);
				assertNotNull(typed, "the query must retain its typed filter feedback contract");
				assertEquals(queryEpoch, typed.getRuntimeFeedbackContract().dataEpoch());
				try (var rows = step.evaluate(EmptyBindingSet.getInstance())) {
					assertTrue(rows.hasNext(), "the query has started on its committed snapshot");
					if (boundary != Boundary.FINISH_BEFORE_PUBLICATION) {
						commitOne(repository);
						assertNotEquals(queryEpoch, store.getBackingStore().dataRevision());
						if (boundary == Boundary.COMMIT_BEFORE_PUBLICATION) {
							release.countDown();
							LmdbTestUtil.awaitPostReadyInitialization(store, 30, TimeUnit.SECONDS);
						}
					}
					int count = 0;
					Set<String> actual = new HashSet<>();
					while (rows.hasNext()) {
						actual.add(rows.next().getValue("s").stringValue());
						count++;
					}
					Set<String> expected = new HashSet<>();
					for (int i = 0; i < 128; i += 4) {
						expected.add("urn:early:s:" + i);
					}
					assertEquals(32, count, "the old snapshot preserves its complete result bag");
					assertEquals(expected, actual);
				}
				if (boundary == Boundary.FINISH_BEFORE_PUBLICATION
						|| boundary == Boundary.COMMIT_AND_FINISH_BEFORE_PUBLICATION) {
					release.countDown();
					LmdbTestUtil.awaitPostReadyInitialization(store, 30, TimeUnit.SECONDS);
				}
				if (boundary == Boundary.FINISH_BEFORE_PUBLICATION) {
					assertTrue(store.getBackingStore().learnedFilterSelectivity().size() > 0,
							"an exhausted query finishing before publication must teach without a later query");
				} else {
					assertEquals(0, store.getBackingStore().learnedFilterSelectivity().size(),
							"a query from the prior snapshot must not teach the committed replacement");
				}
			}
		} finally {
			release.countDown();
			repository.shutDown();
		}
	}

	private static void populate(SailRepository repository) {
		try (var connection = repository.getConnection()) {
			var values = connection.getValueFactory();
			connection.begin();
			for (int i = 0; i < 128; i++) {
				connection.add(values.createIRI("urn:early:s:" + i), values.createIRI("urn:early:p"),
						values.createLiteral((i % 4 == 0 ? "hit:" : "miss:") + i));
			}
			connection.commit();
		}
	}

	private static void commitOne(SailRepository repository) {
		try (var connection = repository.getConnection()) {
			var values = connection.getValueFactory();
			connection.add(values.createIRI("urn:early:new"), values.createIRI("urn:early:p"),
					values.createLiteral("miss:new"));
		}
	}

	private static Filter filter() {
		TupleExpr root = QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL, QUERY, null).getTupleExpr();
		PlanningGraphDomains.capture(root, PlanningGraphDomain.defaultGraph());
		return findFilter(root, false);
	}

	private static Filter findFilter(TupleExpr root, boolean typed) {
		Filter[] found = new Filter[1];
		root.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(Filter filter) {
				if (found[0] == null && (!typed || filter.getRuntimeFeedbackContract() != null
						&& filter.getRuntimeFeedbackContract().admits(RuntimeFeedbackContract.ADMIT_FILTER))) {
					found[0] = filter;
				}
				super.meet(filter);
			}
		});
		return found[0];
	}

	private static final class HeldStore extends LmdbStore {
		private final CountDownLatch entered;
		private final CountDownLatch release;

		private HeldStore(Path path, CountDownLatch entered, CountDownLatch release) {
			super(path.toFile(), config());
			this.entered = entered;
			this.release = release;
		}

		private static LmdbStoreConfig config() {
			LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc,ospc");
			config.setNativeEvaluationEnabled(false);
			config.setFrontierEstimatorMode(FrontierEstimatorMode.OFF);
			config.setExperimentalQueryOptimizations(true);
			return config;
		}

		@Override
		LmdbSailStore createBackingStore(File directory, StoreProperties properties, LmdbStoreConfig config,
				boolean sketches) throws IOException, SailException {
			return new LmdbSailStore(directory, properties, config, sketches, null,
					(tripleDir, props, settings, values) -> new TripleStore(tripleDir, props, settings, values) {
						@Override
						void startBackgroundIndexRebuild() {
							entered.countDown();
							try {
								release.await();
							} catch (InterruptedException failure) {
								Thread.currentThread().interrupt();
								return;
							}
							super.startBackgroundIndexRebuild();
						}
					});
		}
	}
